// Conversion of open file descriptor to DIR stream

// Setup:
// Requires open(2) flags: O_RDONLY | O_DIRECTORY
int dir_fd = open("/etc", O_RDONLY | O_DIRECTORY);

DIR *dir_stream = NULL;

if (dir_fd >= 0) {
    dir_stream = fdopendir(dir_fd);
}

// Ownership Rule:
if (dir_stream == NULL) {
    // fdopendir failed: Manual close required
    if (dir_fd >= 0) close(dir_fd);
} else {
    // Success: fd ownership transferred to dir_stream
    struct dirent *entry = readdir(dir_stream);

    // Cleanup via closedir(3)
    closedir(dir_stream); // Closes both DIR* and the underlying fd
}
